#!/bin/bash
# The git guard's main gate and force gate: the refspec and push option
# grammar, git's global options, command prefixes, groups and comments
# (design § 2.2 P4 to P6, § 12.3), and the source suite's push rows moved here.
# Every row runs at the plugin's defaults (push_to_main ask, force_push ask,
# commit_style off) from REPO_FEATURE unless it says otherwise; every ask row
# also runs unattended and expects a deny with the same code.
# Command strings are inert JSON data and are never executed.
set -u
LC_ALL=C
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SUITE=push
. "$HERE/fixtures/git-guard/harness.sh"

printf '%s\n' '== Main gate (M rows) =='
gg_row "M-1 push to main" ask:push_main_branch 'git push origin main'
gg_row "M-2 push to master" ask:push_main_branch 'git push origin master'
gg_row "M-3 HEAD:main" ask:push_main_branch 'git push origin HEAD:main'
gg_row "M-4 HEAD:refs/heads/main" ask:push_main_branch 'git push origin HEAD:refs/heads/main'
gg_row "M-5 feature:main" ask:push_main_branch 'git push origin feature:main'
gg_row "M-6 main:main" ask:push_main_branch 'git push origin main:main'
gg_row "M-7 another remote" ask:push_main_branch 'git push fork main'
gg_row "M-8 refs/heads/main" ask:push_main_branch 'git push origin refs/heads/main'
gg_row "M-9 heads/main" ask:push_main_branch 'git push origin heads/main'
gg_row "M-10 HEAD:MAIN" ask:push_main_branch 'git push origin HEAD:MAIN'
gg_row "M-11 --all" ask:push_all_branches 'git push --all origin'
gg_row "M-12 --branches" ask:push_all_branches 'git push --branches origin'
gg_row "M-13 matching refspec" ask:push_matching_refspec 'git push origin :'
gg_row "M-14 wildcard refspec" ask:push_pattern_refspec "git push origin 'refs/heads/*:refs/heads/*'"
gg_row "M-15 -C before push" ask:push_main_branch 'git -C /some/path push origin main'
gg_row "M-16 --git-dir before push" ask:push_main_branch 'git --git-dir=.git push origin main'
gg_row "M-17 the repository word read as a refspec" ask:push_main_branch 'git push HEAD:main'
gg_row "M-18 feature push" silent 'git push origin feature'
gg_row "M-19 HEAD:feature" silent 'git push origin HEAD:feature'
gg_row "M-20 an -o value is not the repository" silent 'git push -o main origin feature'
gg_row "M-21 a comment after the push" silent 'git push origin feature # to main'
gg_row "M-G1 brace group" ask:push_main_branch '{ git push origin main; }'
gg_row "M-G2 subshell" ask:push_unreadable_word '(git push origin main)'
gg_row "M-G3 if then" ask:push_main_branch 'if true; then git push origin main; fi'
gg_row "M-G4 function body" ask:push_main_branch 'f() { git push origin main; }; f'
gg_row "M-G5 case arm" ask:push_main_branch 'case x in x) git push origin main;; esac'
gg_row "M-G6 dashed command word" ask:push_main_branch 'git-push origin main'
gg_row "M-G7 PUSH in capitals" ask:push_main_branch 'git PUSH origin main'
gg_row "M-G8 a redirection after the words" ask:push_main_branch 'git push origin main 2>&1'
gg_row "M-G9 master in capitals" ask:push_main_branch 'git push origin MASTER'

printf '%s\n' '== Force gate (F rows) =='
gg_row "F-1 -f" ask:push_force 'git push -f origin feature'
gg_row "F-2 -uf cluster" ask:push_force 'git push -uf origin feature'
gg_row "F-3 --forc, a prefix of three force options" ask:push_unknown_option 'git push --forc origin feature'
gg_row "F-4 --force-with-lease=" ask:push_force 'git push --force-with-lease=feature:abc origin feature'
gg_row "F-5 --force-if-includes" ask:push_force 'git push --force-if-includes origin feature'
gg_row "F-6 + refspec" ask:push_force 'git push origin +feature'
gg_row "F-7 -d" ask:push_delete 'git push -d origin feature'
gg_row "F-8 --del" ask:push_delete 'git push --del origin feature'
gg_row "F-9 :feature" ask:push_delete 'git push origin :feature'
gg_row "F-10 --mirror (force before main)" ask:push_mirror 'git push --mirror origin'
gg_row "F-11 --prune" ask:push_prune "git push --prune origin 'refs/heads/*:refs/heads/*'"
gg_row "F-12 -of is -o with the value f" silent 'git push -of origin feature'
gg_row "F-13 --no-force" silent 'git push --no-force origin feature'
gg_row "F-14 -d main (force and main)" ask:push_delete 'git push -d origin main'
gg_row "F-15 a force option after the operands" ask:push_force 'git push origin feature --force'
gg_row "F-16 a delete option after the operands" ask:push_delete 'git push origin feature -d'
gg_row "F-17 a flag after main is not a refspec" ask:push_main_branch 'git push origin main --dry-run'
gg_row "F-18 after -- it is a refspec" silent 'git push origin -- --force'
gg_row "F-19 an -o value after the operands" silent 'git push origin feature -o main'
gg_row "F-20 --mirr abbreviation" ask:push_mirror 'git push --mirr origin'
gg_row "F-21 --pru abbreviation" ask:push_prune 'git push --pru origin feature'
gg_row "F-22 force sign on a HEAD refspec" ask:push_force 'git push origin +HEAD:feature'
gg_row "F-23 --force=x takes no value" ask:push_unknown_option 'git push --force=x origin feature'
gg_row "F-24 -d with a + name" ask:push_delete 'git push -d origin +main'

printf '%s\n' '== Presumed (P-U rows) =='
gg_row "P-U1 a variable refspec" ask:push_unreadable_word 'git push origin $B'
gg_row "P-U2 a brace refspec" ask:push_unreadable_word 'git push origin {main,x}'
gg_row "P-U3 an unknown push option" ask:push_unknown_option 'git push --frobnicate origin feature'
gg_row "P-U4 an ambiguous prefix" ask:push_unknown_option 'git push --f origin feature'
gg_row "P-U5 an unknown git option" ask:push_unknown_git_option 'git --future-option push origin feature'
gg_row "P-U6 --receive-pack" ask:push_receive_pack 'git push --receive-pack=x origin feature'
gg_row "P-U7 git subtree push" ask:push_subtree 'git subtree push --prefix d origin feature'
gg_row "P-U8 git send-pack" ask:push_send_pack 'git send-pack origin feature'
gg_row "P-U9 a prefix option the skipper does not read" ask:push_unsupported_prefix 'timeout -s KILL 5 git push origin feature'
gg_row "P-U10 an unlisted wrapper" ask:push_beside_wrapper 'chronic git push origin feature'
gg_row "P-U11 -c on a push" ask:push_config_override 'git -c core.sshCommand=x push origin feature'
P_U12="$(python3 -I -c 'print("echo " + "a" * 6500 + " && git push origin feature")')"
gg_row "P-U12 a 6,500-byte command ending in a push" ask:push_command_too_long "$P_U12"
P_U12_SILENT="$(python3 -I -c 'print("echo " + "a" * 6500 + " && git status")')"
gg_row "P-U12b an over-long command with no push word" silent "$P_U12_SILENT"
gg_row "P-U13 an unknown short option" ask:push_unknown_option 'git push -x origin feature'
gg_row "P-U14 --exec" ask:push_receive_pack 'git push --exec x origin feature'
gg_row "P-U15 a variable subcommand word" ask:push_unreadable_word 'git ${P:-push} origin feature'
gg_row "P-U16 a variable in an -o value" ask:push_unreadable_word 'git push -o "$X" origin feature'
gg_row "P-U17 dashed send-pack" ask:push_send_pack 'git-send-pack origin feature'
gg_row "P-U18 a tilde path is not literal" ask:push_unreadable_word 'git push ~/repo feature'
gg_row "P-U19 a quoted push subcommand is read" ask:push_force 'git -C . "push" --force origin feature'
gg_row "P-U20 a push segment that does not split" ask:push_unreadable_segment 'git push origin "feature'

printf '%s\n' '== Prefixes, wrappers and comments =='
gg_row "W-1 env prefix" silent 'env FOO=1 git push origin feature'
gg_row "W-2 env prefix, force" ask:push_force 'env X=1 git push --force origin main'
gg_row "W-3 sudo, force" ask:push_force 'sudo git push -f origin feature'
gg_row "W-4 echo is data" silent 'echo git push --force origin main'
gg_row "W-5 printf is data" silent "printf '%s\\n' 'git push --force origin main' >> notes.md"
gg_row "W-6 ssh to another machine" ask:push_beside_wrapper 'ssh host git push origin main'
gg_row "W-7 a comment line, then a feature push" silent $'# never git push --force to main\ngit push origin feature'
gg_row "W-8 grep mentions push" silent 'grep -n push notes.md'
gg_row "W-9 a later dashed git-push word" ask:push_beside_wrapper 'chronic git-push origin feature'
gg_row "W-10 nohup, a feature push" silent 'nohup git push origin feature'
gg_row "W-11 an assignment, force" ask:push_force 'VAR="some text" git push --force origin main'

printf '%s\n' '== Rows moved from the source suite (GT:<line> is the source line) =='
GG_COMMIT=off
gg_row_at "$REPO_FEATURE" $'GT:948 global option -C /some/path: destructive push' ask $'git -C /some/path push --force origin main'
gg_row_at "$REPO_FEATURE" $'GT:952 global option -C /some/path: feature push' silent $'git -C /some/path push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:948 global option -c core.x=y: destructive push' ask $'git -c core.x=y push --force origin main'
gg_row_at "$REPO_FEATURE" $'GT:952 global option -c core.x=y: feature push' ask $'git -c core.x=y push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:948 global option --git-dir=/x/.git: destructive push' ask $'git --git-dir=/x/.git push --force origin main'
gg_row_at "$REPO_FEATURE" $'GT:952 global option --git-dir=/x/.git: feature push' silent $'git --git-dir=/x/.git push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:948 global option --git-dir /x/.git: destructive push' ask $'git --git-dir /x/.git push --force origin main'
gg_row_at "$REPO_FEATURE" $'GT:952 global option --git-dir /x/.git: feature push' silent $'git --git-dir /x/.git push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:948 global option --work-tree=/x: destructive push' ask $'git --work-tree=/x push --force origin main'
gg_row_at "$REPO_FEATURE" $'GT:952 global option --work-tree=/x: feature push' silent $'git --work-tree=/x push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:948 global option --work-tree /x: destructive push' ask $'git --work-tree /x push --force origin main'
gg_row_at "$REPO_FEATURE" $'GT:952 global option --work-tree /x: feature push' silent $'git --work-tree /x push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:948 global option --namespace=ns: destructive push' ask $'git --namespace=ns push --force origin main'
gg_row_at "$REPO_FEATURE" $'GT:952 global option --namespace=ns: feature push' silent $'git --namespace=ns push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:948 global option --namespace ns: destructive push' ask $'git --namespace ns push --force origin main'
gg_row_at "$REPO_FEATURE" $'GT:952 global option --namespace ns: feature push' silent $'git --namespace ns push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:948 global option --no-pager: destructive push' ask $'git --no-pager push --force origin main'
gg_row_at "$REPO_FEATURE" $'GT:952 global option --no-pager: feature push' silent $'git --no-pager push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:948 global option -P: destructive push' ask $'git -P push --force origin main'
gg_row_at "$REPO_FEATURE" $'GT:952 global option -P: feature push' silent $'git -P push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:948 global option -p: destructive push' ask $'git -p push --force origin main'
gg_row_at "$REPO_FEATURE" $'GT:952 global option -p: feature push' silent $'git -p push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:948 global option --paginate: destructive push' ask $'git --paginate push --force origin main'
gg_row_at "$REPO_FEATURE" $'GT:952 global option --paginate: feature push' silent $'git --paginate push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:948 global option --bare: destructive push' ask $'git --bare push --force origin main'
gg_row_at "$REPO_FEATURE" $'GT:952 global option --bare: feature push' silent $'git --bare push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:948 global option --no-replace-objects: destructive push' ask $'git --no-replace-objects push --force origin main'
gg_row_at "$REPO_FEATURE" $'GT:952 global option --no-replace-objects: feature push' silent $'git --no-replace-objects push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:948 global option --literal-pathspecs: destructive push' ask $'git --literal-pathspecs push --force origin main'
gg_row_at "$REPO_FEATURE" $'GT:952 global option --literal-pathspecs: feature push' silent $'git --literal-pathspecs push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:948 global option --exec-path=/x: destructive push' ask $'git --exec-path=/x push --force origin main'
gg_row_at "$REPO_FEATURE" $'GT:952 global option --exec-path=/x: feature push' silent $'git --exec-path=/x push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:948 global option --exec-path /x: destructive push' ask $'git --exec-path /x push --force origin main'
gg_row_at "$REPO_FEATURE" $'GT:952 global option --exec-path /x: feature push' silent $'git --exec-path /x push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:948 global option --config-env=F=env: destructive push' ask $'git --config-env=F=env push --force origin main'
gg_row_at "$REPO_FEATURE" $'GT:952 global option --config-env=F=env: feature push' ask $'git --config-env=F=env push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:948 global option --no-optional-locks: destructive push' ask $'git --no-optional-locks push --force origin main'
gg_row_at "$REPO_FEATURE" $'GT:952 global option --no-optional-locks: feature push' silent $'git --no-optional-locks push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1051 quoted git-dir: force push' ask $'git --git-dir=".git" push --force origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1053 quoted git-dir: lease' ask $'git --git-dir=".git" push --force-with-lease origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1055 quoted git-dir: force refspec' ask $'git --git-dir=".git" push origin +feature'
gg_row_at "$REPO_FEATURE" $'GT:1057 quoted git-dir: mirror' ask $'git --git-dir=".git" push --mirror origin'
gg_row_at "$REPO_FEATURE" $'GT:1059 quoted git-dir: delete' ask $'git --git-dir=".git" push --delete origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1061 quoted git-dir: deletion refspec' ask $'git --git-dir=".git" push origin :feature'
gg_row_at "$REPO_FEATURE" $'GT:1063 quoted git-dir: main push' ask $'git --git-dir=".git" push origin main'
gg_row_at "$REPO_FEATURE" $'GT:1069 escaped git command' ask $'\\git -C . push --force origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1071 absolute git command' ask $'/usr/bin/git -C . push --force origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1074 env unset wrapper' ask $'env -u FOO git -C . push --force origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1076 command path wrapper' ask $'command -p git -C . push --force origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1079 quoted push subcommand' ask $'git -C . "push" --force origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1081 quoted force option' ask $'git -C . push "--force" origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1083 quoted force refspec' ask $'git -C . push origin "+feature"'
gg_row_at "$REPO_FEATURE" $'GT:1085 quoted deletion refspec' ask $'git -C . push origin ":feature"'
gg_row_at "$REPO_FEATURE" $'GT:1088 env wrapped shell payload' ask $'env FOO=y sh -c \'git -C . push --force origin feature\''
gg_row_at "$REPO_FEATURE" $'GT:1091 absolute git short force' ask $'/usr/bin/git -C . push -f origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1094 xargs git short force' ask $'xargs git -C x push -f origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1097 eval quoted push' ask $'eval "git -C x push -f origin feature"'
gg_row_at "$REPO_FEATURE" $'GT:1100 force push through git alias' ask $'git -c alias.p=\'push --force\' p origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1102 delete push through git alias' ask $'git -c alias.p=\'push --delete\' p origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1104 mirror push through git alias' ask $'git -c alias.p=\'push --mirror\' p origin'
gg_row_at "$REPO_FEATURE" $'GT:1106 force refspec through git alias' ask $'git -c alias.p=\'push origin +feature\' p'
gg_row_at "$REPO_FEATURE" $'GT:1109 quoted no-pager option' ask $'git "--no-pager" push --force origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1111 quoted -C option' ask $'git "-C" /tmp push --force origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1114 quoted semicolon in config value' ask $'git -c foo=\'x;y\' push --force origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1117 bash login flag cluster' ask $'bash -lc \'git --no-pager push --force origin feature\''
gg_row_at "$REPO_FEATURE" $'GT:1119 bash errexit flag cluster' ask $'bash -ec \'git --no-pager push --force origin feature\''
gg_row_at "$REPO_FEATURE" $'GT:1121 sh double dash payload' ask $'sh -c -- \'git --no-pager push --force origin feature\''
gg_row_at "$REPO_FEATURE" $'GT:1124 unsupported substitution fails closed' ask $'git -c foo=`printf x` push --force origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1127 xargs count option before force push' ask $'printf feature | xargs -n 1 git -C . push -f origin'
gg_row_at "$REPO_FEATURE" $'GT:1129 xargs attached count before force push' ask $'printf feature | xargs -n1 git push --force origin'
gg_row_at "$REPO_FEATURE" $'GT:1131 xargs count option before feature push' ask $'printf feature | xargs -n 1 git push origin'
gg_row_at "$REPO_FEATURE" $'GT:1134 eval joins separate arguments' ask $'eval git -C . push -f origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1136 eval joins quoted arguments' ask $'eval \'git\' \'push --force origin feature\''
gg_row_at "$REPO_FEATURE" $'GT:1138 eval joins feature push arguments' ask $'eval git push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1141 unrelated alias does not replace push alias' ask $'git -c alias.p=\'push --force\' -c alias.q=status p origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1144 shell alias force push' ask $'git -c alias.p=\'!git push --force\' p origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1146 shell alias delete push' ask $'git -c alias.p=\'!git push --delete\' p origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1149 alias chain force push' ask $'git -c alias.p=push -c alias.q=\'p -f\' q origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1152 substitution generates deletion refspec' ask $'git push origin $(printf :feature)'
gg_row_at "$REPO_FEATURE" $'GT:1157 rcfile precedes shell payload' ask $'bash --rcfile /dev/null -c \'git push --force origin feature\''
gg_row_at "$REPO_FEATURE" $'GT:1159 rcfile precedes feature push' ask $'bash --rcfile /dev/null -c \'git push origin feature\''
gg_row_at "$REPO_FEATURE" $'GT:1162 negated force push' ask $'! git push --force origin feature'
gg_row_at "$REPO_FEATURE" $'GT:967 closed_xargs 1' ask $'printf :feature | xargs -n 1 git push origin'
gg_row_at "$REPO_FEATURE" $'GT:967 closed_xargs 2' ask $'printf \'%s\' --force | xargs -I \'{}\' git push \'{}\' origin feature'
gg_row_at "$REPO_FEATURE" $'GT:967 closed_xargs 3' ask $'printf \'push -f\' | xargs git'
gg_row_at "$REPO_FEATURE" $'GT:967 closed_xargs 4' ask $'printf feature | xargs --replace git push -f origin feature'
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 1' ask $'nohup git push -f origin feature'
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 2' ask $'timeout 5 git push -f origin feature'
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 3' ask $'nice git push -f origin feature'
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 4' ask $'stdbuf -o0 git push -f origin feature'
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 5' ask $'setsid git push -f origin feature'
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 6' ask $'script -q /dev/null git push -f origin feature'
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 7' ask $'sudo git push -f origin feature'
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 8' ask $'doas git push -f origin feature'
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 9' ask $'exec git push -f origin feature'
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 10' ask $'obscure-wrapper git push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 11' ask $'env FOO=1 obscure-wrapper git push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 12' ask $'command obscure-wrapper git push origin feature'
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 13' ask $'env -C /tmp git push -f origin feature'
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 14' ask $'env -S \'git push -f origin feature\''
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 15' ask $'zsh -c \'git push -f origin feature\''
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 16' ask $'dash -c \'git push -f origin feature\''
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 17' ask $'ksh -c \'git push -f origin feature\''
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 18' ask $'fish -c \'git push -f origin feature\''
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 19' ask $'bash <<< \'git push -f origin feature\''
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 20' ask $'echo \'git push -f origin feature\' | sh'
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 21' ask $'echo \'git push -f origin feature\' | bash'
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 22' ask $'echo \'git push -f origin feature\' | xargs -I{} sh -c {}'
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 23' ask $'find . -exec git push -f origin feature \\;'
gg_row_at "$REPO_FEATURE" $'GT:995 closed_wrappers 24' ask $'find . -execdir git push -f origin feature \\;'
gg_row_at "$REPO_FEATURE" $'GT:1007 closed_alias 1' ask $'git -c ALIAS.p=\'push -f\' p origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1007 closed_alias 2' ask $'git -c Alias.p=\'!git push -f\' p origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1007 closed_alias 3' ask $'git -c alias.P=\'push -f\' p origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1007 closed_alias 4' ask $'git -c ALIAS.p=\'log --oneline -1\' p'
gg_row_at "$REPO_FEATURE" $'GT:1007 closed_alias 5' ask $'GIT_CONFIG_PARAMETERS="\'alias.p=push -f\'" git p origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1007 closed_alias 6' ask $'GIT_CONFIG_COUNT=1 GIT_CONFIG_KEY_0=alias.p GIT_CONFIG_VALUE_0=\'push -f\' git p origin feature'
gg_row_at "$REPO_FEATURE" $'GT:1007 closed_alias 7' ask $'git --config-env=alias.p=VAR p origin feature'
